from pages import L,IG,FB,META,EU,STEPS
REL=L('instagram-appeal-links-and-forms-directory','Instagram appeal links')+', '+L('guides/instagram-account-integrity','account integrity guide')+', '+L('how-to-contact-meta-about-a-disabled-account','how to contact Meta')+', '+L('guides/instagram-disabled-no-appeal-button','no appeal button')+', '+L('instagram-account-ban-service','Instagram unban help')+'.'
PAGES=[
dict(slug='instagram-disabled-because-of-a-linked-account',title='Instagram Disabled Because of a Linked Account: What It Means',crumb='Disabled because of a linked account',listname='Official Instagram links for linked-account disables',
 desc='Your Instagram was disabled because it is linked to another account that broke the rules, and you do not recognise that account. What “linked” usually means and how to appeal.',
 h1='Disabled because of an account you do not recognise.',lede='When Instagram says your account was disabled because it is connected to another account that broke the rules, and you have never heard of that account.',
 answer='<strong>“Linked” usually means Meta saw signals tying the two accounts together, such as the same device, phone number, email, IP address or Accounts Center profile.</strong> It does not need to be an account you own. Shared phones, a family Wi-Fi, a reused phone number or a hacker who logged in from your device can all create a link. Appeal from the notice and explain plainly that you do not control the other account and why the signals might overlap. Meta makes the final decision.',
 cards=[('Shared signals','Device, phone, email or network.'),('Say it plainly','You do not control the other account.'),('Clean up','Remove unknown logins and devices.')],
 pre='<h2 id="common-links">Common reasons two accounts look linked</h2><ul><li>A phone, laptop or tablet used by more than one person.</li><li>A phone number that used to belong to someone else.</li><li>The same home, office, school or hostel Wi-Fi.</li><li>An account added to your Accounts Center, or an old account you forgot.</li><li>A takeover: the person who hacked you logged in to their own accounts from your session.</li></ul>'
  '<h2 id="what-to-write">What to write in the appeal</h2><p>Name your own account and what you use it for. Say that you do not run the other account and do not know who does. Give the likely reason for the overlap in one sentence, for example a shared family phone or a recycled number. Mention any security problem you noticed. Do not guess at the other person’s identity or accuse anyone.</p>',
 sections=[('links','Where to go',[IG[1],IG[0],IG[3],IG[2]])],
 post=['<h2 id="clean-up">Clean up before and after</h2><ol><li>In Accounts Center, remove any profile you do not recognise.</li><li>Check where you are logged in and log out of unknown devices.</li><li>Change your password and turn on two-factor with an authenticator app.</li><li>Stop using shared devices for the account while the appeal is open.</li></ol>',STEPS],
 related=REL,
 faqs=[('Can I be disabled for someone else’s account?','Yes. If Meta’s systems connect your account to one that broke the rules, both can be actioned. You can explain the overlap in the appeal.'),('Should I mention the other username?','Only if the notice names it. Say you do not control it.'),('Will removing the link restore my account?','Removing unknown links and devices is good practice, but only the appeal can reverse a disable.'),('Is my password needed for help?','No. Your password and login codes stay with you.')]),
dict(slug='instagram-account-integrity-appeal-what-to-write',title='Instagram Account Integrity Appeal: What to Write',crumb='Account integrity appeal: what to write',listname='Official Instagram links for account integrity appeals',
 desc='How to write an Instagram appeal when the notice says your account did not follow Community Standards on account integrity. A short structure, what to include and what to leave out.',
 h1='Account integrity appeal: what to write.',lede='A plain structure for the appeal box when Instagram says your account broke its rules on account integrity.',
 answer='<strong>Keep the appeal short, factual and about your own account.</strong> Say who you are, that the account is real and yours, what you use it for, and anything that may have looked unusual, such as a new device, a hack, a third-party app or bought engagement you have since stopped. Do not paste a long letter, threaten legal action or ask for a specific person at Meta. Send it once from the notice on your usual device. Meta makes the final decision.',
 cards=[('Four to six lines','Short appeals are easier to read.'),('Your own words','Copied templates read as spam.'),('Once only','Repeat appeals do not help.')],
 pre='<h2 id="structure">A simple structure</h2><ol><li><strong>Who:</strong> your name and the account’s username.</li><li><strong>What it is:</strong> personal, creator or business, and how long you have had it.</li><li><strong>What may have happened:</strong> one or two sentences, for example a login you did not make, an automation or follower app you used, or a shared device.</li><li><strong>What you changed:</strong> removed the app, changed the password, turned on two-factor.</li><li><strong>The ask:</strong> that the account be looked at again.</li></ol>'
  '<h2 id="leave-out">What to leave out</h2><ul><li>Long letters addressed to “the Meta team” copied from the internet.</li><li>Threats, legal language or demands for compensation.</li><li>Screenshots of unrelated chats or other people’s accounts.</li><li>Claims you cannot back up, such as being verified when you are not.</li></ul>'
  '<h2 id="where">Where to send it</h2><p>Only in the appeal box on the disabled notice or in Account Status. Emailing the letter elsewhere, including to independent services like Unbanz, does not send it to Meta.</p>',
 sections=[('links','Where the appeal goes',[IG[1],IG[0],META[1],META[2]])],
 post=[STEPS],
 related=REL,
 faqs=[('What does account integrity mean on Instagram?','It is a broad label Meta uses when it believes an account was used in ways that break its rules, often linked to spam-like activity, automation, inauthentic engagement or links to other removed accounts.'),('How long should my appeal be?','A few short sentences is enough. Clear and specific beats long.'),('Can I send the appeal by email?','No. Instagram appeals go through the notice in the app or Account Status.'),('My appeal was rejected. Can I write again?','Inside Instagram, a decision after appeal is usually final. EU users may have Digital Services Act routes.')]),
dict(slug='multiple-instagram-accounts-disabled-at-once',title='Multiple Instagram Accounts Disabled at Once: What to Do',crumb='Several accounts disabled at once',listname='Official Instagram links when several accounts are disabled',
 desc='Two or more of your Instagram accounts were disabled on the same day. Why it happens, which one to appeal first, and how to avoid making it worse.',
 h1='Several Instagram accounts disabled at once.',lede='When two or more of your Instagram accounts go down on the same day, usually without a clear reason.',
 answer='<strong>Several accounts going down together usually means Meta treated them as one group.</strong> They may share a device, phone number, email or Accounts Center, and one action can carry across all of them. Appeal each account from its own notice, starting with the one that matters most and has the cleanest history. Do not create new accounts while the appeals are open. Meta makes the final decision.',
 cards=[('One group','Shared signals tie accounts together.'),('Appeal each','Every account has its own notice.'),('No new accounts','New sign-ups can be read as evasion.')],
 pre='<h2 id="why">Why it happens</h2><ul><li>All the accounts sit in the same Accounts Center or share a login.</li><li>One account broke a rule and the others were linked to it.</li><li>A follower, automation or scheduling app was connected to all of them.</li><li>A hacker used your accounts to send spam.</li></ul>'
  '<h2 id="order">Which one to appeal first</h2><p>Start with the main personal or business account, the one with a real name, real photos and the longest history. Write each appeal separately in your own words. Mention in each that you also run the other accounts and what they are for, so the connection is explained rather than hidden.</p>',
 sections=[('links','Where to go',[IG[1],IG[0],IG[3],IG[2]])],
 post=['<h2 id="after">After the appeals</h2><ol><li>Disconnect third-party apps from every account.</li><li>Use two-factor with an authenticator app on each one.</li><li>Keep only the accounts you really use.</li></ol>',STEPS],
 related=REL+' See also '+L('instagram-disabled-because-of-a-linked-account','disabled because of a linked account')+'.',
 faqs=[('Do I need to appeal every account?','Yes. Each account has its own notice and appeal.'),('Will one successful appeal restore the others?','Not always. Each one is decided on its own.'),('Should I make a new account while I wait?','No. New accounts can be treated as trying to get around the disable.'),('Can Unbanz help with more than one account?','Yes, tell us how many accounts and what each notice says.')]),
]
